import * as React from 'react';

export interface HeroAction {
  label: string;
  onClick?: () => void;
  href?: string;
  variant?: 'primary' | 'secondary' | 'outline';
}

export interface HeroSectionProps {
  badge?: React.ReactNode;
  title: React.ReactNode;
  description?: React.ReactNode;
  primaryAction?: HeroAction;
  secondaryAction?: HeroAction;
  media?: React.ReactNode;
  align?: 'center' | 'left';
  showGlow?: boolean;
  glowColor?: string;
  className?: string;
  style?: React.CSSProperties;
}

export const HeroSection: React.FC<HeroSectionProps> = ({
  badge,
  title,
  description,
  primaryAction,
  secondaryAction,
  media,
  align = 'center',
  showGlow = true,
  glowColor = 'rgba(37, 99, 235, 0.15)',
  className = '',
  style,
  ...props
}) => {
  const isCenter = align === 'center';

  return (
    <section
      className={`boost-hero-section ${className}`}
      style={{
        position: 'relative',
        padding: 'clamp(48px, 8vw, 96px) clamp(16px, 4vw, 32px)',
        overflow: 'hidden',
        width: '100%',
        boxSizing: 'border-box',
        ...style,
      }}
      {...props}
    >
      {showGlow && (
        <div
          style={{
            position: 'absolute',
            top: '5%',
            left: isCenter ? '50%' : '30%',
            transform: 'translateX(-50%)',
            width: 'clamp(280px, 45vw, 600px)',
            height: 'clamp(280px, 45vw, 600px)',
            borderRadius: '50%',
            background: glowColor,
            filter: 'blur(clamp(60px, 10vw, 120px))',
            pointerEvents: 'none',
            zIndex: 0,
            animation: 'boost-pulse 6s ease-in-out infinite alternate',
          }}
        />
      )}

      <div
        style={{
          position: 'relative',
          zIndex: 1,
          maxWidth: '1200px',
          margin: '0 auto',
          display: 'flex',
          flexDirection: isCenter ? 'column' : 'row',
          flexWrap: 'wrap',
          alignItems: 'center',
          justifyContent: isCenter ? 'center' : 'space-between',
          gap: 'clamp(32px, 5vw, 56px)',
          textAlign: isCenter ? 'center' : 'left',
        }}
      >
        <div style={{ maxWidth: isCenter ? '820px' : '620px', width: '100%', flex: isCenter ? 'none' : '1 1 300px' }}>
          {badge && (
            <div
              style={{
                display: 'inline-flex',
                alignItems: 'center',
                gap: '8px',
                padding: '6px 14px',
                borderRadius: '9999px',
                backgroundColor: 'rgba(37, 99, 235, 0.1)',
                border: '1px solid rgba(37, 99, 235, 0.22)',
                color: 'var(--boost-primary, #2563eb)',
                fontSize: '13px',
                fontWeight: 600,
                marginBottom: '20px',
                backdropFilter: 'blur(8px)',
                WebkitBackdropFilter: 'blur(8px)',
              }}
            >
              {badge}
            </div>
          )}

          <h1
            style={{
              fontSize: 'clamp(32px, 5.2vw, 60px)',
              fontWeight: 800,
              lineHeight: 1.12,
              letterSpacing: '-0.035em',
              margin: '0 0 20px 0',
              color: 'var(--boost-text, #0f172a)',
            }}
          >
            {title}
          </h1>

          {description && (
            <p
              style={{
                fontSize: 'clamp(15px, 2vw, 19px)',
                lineHeight: 1.65,
                color: 'var(--boost-text-muted, #64748b)',
                margin: '0 0 32px 0',
                maxWidth: isCenter ? '700px' : '100%',
                marginLeft: isCenter ? 'auto' : 0,
                marginRight: isCenter ? 'auto' : 0,
              }}
            >
              {description}
            </p>
          )}

          {(primaryAction || secondaryAction) && (
            <div
              style={{
                display: 'flex',
                flexWrap: 'wrap',
                gap: '12px',
                justifyContent: isCenter ? 'center' : 'flex-start',
                alignItems: 'center',
              }}
            >
              {primaryAction && (
                <button
                  type="button"
                  onClick={primaryAction.onClick}
                  style={{
                    padding: '13px 28px',
                    borderRadius: 'var(--boost-radius, 12px)',
                    backgroundColor: 'var(--boost-primary, #2563eb)',
                    color: '#ffffff',
                    fontSize: '15px',
                    fontWeight: 600,
                    border: 'none',
                    cursor: 'pointer',
                    boxShadow: 'var(--boost-shadow-glow, 0 4px 16px rgba(37, 99, 235, 0.35))',
                    transition: 'all 0.15s ease',
                  }}
                >
                  {primaryAction.label}
                </button>
              )}

              {secondaryAction && (
                <button
                  type="button"
                  onClick={secondaryAction.onClick}
                  style={{
                    padding: '13px 28px',
                    borderRadius: 'var(--boost-radius, 12px)',
                    backgroundColor: 'var(--boost-surface, transparent)',
                    color: 'var(--boost-text, inherit)',
                    fontSize: '15px',
                    fontWeight: 600,
                    border: '1px solid var(--boost-border, #cbd5e1)',
                    cursor: 'pointer',
                    transition: 'all 0.15s ease',
                  }}
                >
                  {secondaryAction.label}
                </button>
              )}
            </div>
          )}
        </div>

        {media && (
          <div
            style={{
              flex: isCenter ? 'none' : '1 1 320px',
              width: '100%',
              maxWidth: isCenter ? '900px' : '540px',
              display: 'flex',
              justifyContent: 'center',
              alignItems: 'center',
              borderRadius: 'var(--boost-radius, 16px)',
              overflow: 'hidden',
            }}
          >
            {media}
          </div>
        )}
      </div>
    </section>
  );
};


HeroSection.displayName = 'HeroSection';
